import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  Drawer,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  IconButton,
  Modal,
  Box,
  useTheme,
  Button,
} from "@mui/material";
import {
  Dashboard as DashboardIcon,
  PowerSettingsNew as PowerSettingsNewIcon,
  People as PeopleIcon,
} from "@mui/icons-material";
import { TrackChanges as TrackChangesIcon } from "@mui/icons-material";
import "./Sidebar.css";
import MenuIcon from "@mui/icons-material/Menu";

const SidebarHr = () => {
  const navigate = useNavigate();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [region, setRegion] = useState("");

  useEffect(() => {
    const userRegion = localStorage.getItem("region");
    if (userRegion) {
      setRegion(userRegion);
    } else {
      console.error("Region not found in local storage");
    }
  }, []);

  const handleLogoutClick = () => {
    setShowModal(true);
  };

  const confirmLogout = () => {
    setShowModal(false);
    localStorage.clear();
    sessionStorage.clear();
    navigate("/");
  };

  const cancelLogout = () => {
    setShowModal(false);
  };

  const handleLinkClick = (path) => {
    navigate(path);
    setIsSidebarOpen(false);
  };

  const toggleSidebar = () => {
    setIsSidebarOpen((prev) => !prev);
  };

  const goToReviewRequestForm = () => {
    navigate("/Simtracker");
  };
  const theme = useTheme();

  return (
    <>
      <Drawer
        variant="permanent"
        open={isSidebarOpen}
        sx={{
          width: isSidebarOpen ? 240 : 72,
          flexShrink: 0,

          "& .MuiDrawer-paper": {
            width: isSidebarOpen ? 240 : 72,
            boxSizing: "border-box",
            transition: "width 0.3s",
            // backgroundColor: "#003366",
            backgroundColor:
              theme.palette.mode === "dark" ? "#2a2a2a" : "#003366",
            color: "white",
            display: "flex",
            flexDirection: "column",
            // alignItems: isSidebarOpen ? "flex-start" : "center",
            overflow: "hidden",
          },
        }}
      >
        <List>
          <ListItemIcon>
            <IconButton
              onClick={toggleSidebar}
              className="in_out"
              sx={{
                margin: "8px",
                ml: "auto",
                color: "white",
              }}
            >
              <MenuIcon />
            </IconButton>
          </ListItemIcon>
          {/* <List sx={{ flexGrow: 1, width: "100%", padding: 0 }}> */}
          <ListItem
            button
            onClick={() => handleLinkClick("/HrDashboard")}
            sx={{
              justifyContent: isSidebarOpen ? "flex-start" : "center",
              minHeight: "50px",
              paddingLeft: isSidebarOpen ? "10px" : "30px",
            }}
          >
            <ListItemIcon sx={{ color: "white" }}>
              <i className="fs-4 bi-speedometer2"></i>
            </ListItemIcon>
            {isSidebarOpen && <ListItemText primary="Dashboard" />}
          </ListItem>
          <ListItem
            button
            onClick={() => handleLinkClick("/simrequest")}
            sx={{
              justifyContent: isSidebarOpen ? "flex-start" : "center",
              minHeight: "50px",
              paddingLeft: isSidebarOpen ? "10px" : "30px",
            }}
          >
            <ListItemIcon sx={{ color: "white" }}>
              <PeopleIcon />
            </ListItemIcon>
            {isSidebarOpen && <ListItemText primary="CUG allotment" />}
          </ListItem>
          {region === "Head Office" && (
            <ListItem
              button
              onClick={() => handleLinkClick("/Regionalrequest")}
              sx={{
                justifyContent: isSidebarOpen ? "flex-start" : "center",
                minHeight: "50px",
                paddingLeft: isSidebarOpen ? "10px" : "30px",
              }}
            >
              <ListItemIcon sx={{ color: "white" }}>
                <i className="fs-4 bi-geo-alt"></i>
              </ListItemIcon>
              {isSidebarOpen && <ListItemText primary="Requests " />}
            </ListItem>
          )}

          <ListItem
            button
            onClick={() => handleLinkClick("/SwapSim")}
            sx={{
              justifyContent: isSidebarOpen ? "flex-start" : "center",
              minHeight: "50px",
              paddingLeft: isSidebarOpen ? "10px" : "30px",
            }}
          >
            <ListItemIcon sx={{ color: "white" }}>
              <i className="fs-4 bi-arrow-repeat"></i>
            </ListItemIcon>
            {isSidebarOpen && <ListItemText primary="Swap Sim Request" />}
          </ListItem>
          <ListItem
            button
            onClick={goToReviewRequestForm}
            sx={{
              justifyContent: isSidebarOpen ? "flex-start" : "center",
              minHeight: "50px",
              paddingLeft: isSidebarOpen ? "10px" : "30px",
            }}
          >
            <ListItemIcon sx={{ color: "white" }}>
              <TrackChangesIcon />
            </ListItemIcon>
            {isSidebarOpen && <ListItemText primary="Sim Record" />}
          </ListItem>
          <ListItem
            button
            onClick={handleLogoutClick}
            sx={{
              justifyContent: isSidebarOpen ? "flex-start" : "center",
              minHeight: "50px",
              paddingLeft: isSidebarOpen ? "10px" : "30px",
            }}
          >
            <ListItemIcon sx={{ color: "white" }}>
              <i className="fs-4 bi-box-arrow-right"></i>
            </ListItemIcon>
            {isSidebarOpen && <ListItemText primary="Logout" />}
          </ListItem>
        </List>
      </Drawer>

      <Modal
        open={showModal}
        onClose={cancelLogout}
        aria-labelledby="modal-title"
        aria-describedby="modal-description"
      >
        <Box
          sx={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: 500,
            bgcolor: "background.paper",
            border: "2px solid #000",
            boxShadow: 24,
            p: 4,
          }}
        >
          <h2 id="modal-title">Confirm Logout</h2>
          <p id="modal-description">Are you sure you want to log out?</p>
          <Box sx={{ display: "flex", justifyContent: "flex-end", gap: 1 }}>
            <Button onClick={cancelLogout}>Cancel</Button>
            <Button variant="contained" color="primary" onClick={confirmLogout}>
              Logout
            </Button>
          </Box>
        </Box>
      </Modal>
    </>
  );
};

export default SidebarHr;
