
import React from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper
} from '@mui/material';
import { styled } from '@mui/system';

const StyledTableContainer = styled(TableContainer)(({ theme }) => ({
  maxHeight: 380,
}));

const StyledTableHead = styled(TableHead)(({ theme }) => ({
  position: 'sticky',
  top: 0,
  backgroundColor: theme.palette.mode === 'light' ? '#cfe8fc' : theme.palette.background.paper, 
  zIndex: theme.zIndex.appBar,
  '& .MuiTableCell-root': {
    fontWeight: 'bold', 
  }
}));


const CugNumberTable = ({ cugData, search }) => {
  const filteredCugData = cugData.filter((data) => {
    return (
      data.cugNumber?.toLowerCase().includes(search.toLowerCase()) ||
      data.employeeName?.toLowerCase().includes(search.toLowerCase()) ||
      data.employeeCode?.toLowerCase().includes(search.toLowerCase()) ||
      data.telecomPartner?.toLowerCase().includes(search.toLowerCase())
    );
  });

  return (
    <StyledTableContainer component={Paper}>
      <Table>
        <StyledTableHead>
          <TableRow>
            <TableCell>CUG Number</TableCell>
            <TableCell>Status</TableCell>
            <TableCell>Employee Code</TableCell>
            <TableCell>Employee Name</TableCell>
            <TableCell>Telecom Partner</TableCell>
            <TableCell>Recharge Plan</TableCell>
            <TableCell>Assigned Date</TableCell>
          </TableRow>
        </StyledTableHead>
        <TableBody>
          {filteredCugData.length > 0 ? (
            filteredCugData.map((data, index) => (
              <TableRow key={index}>
                <TableCell>{data.cugNumber || 'N/A'}</TableCell>
                <TableCell>{data.status || 'N/A'}</TableCell>
                <TableCell>{data.employeeCode || 'N/A'}</TableCell>
                <TableCell>{data.employeeName || 'N/A'}</TableCell>
                <TableCell>{data.telecomPartner || 'N/A'}</TableCell>
                <TableCell>{data.rechargePlan || 'N/A'}</TableCell>
                <TableCell>{data.assignedDate ? new Date(data.assignedDate).toLocaleDateString() : 'N/A'}</TableCell>
              </TableRow>
            ))
          ) : (
            <TableRow>
              <TableCell colSpan={7} align="center">No matching records found.</TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
    </StyledTableContainer>
  );
}


export default CugNumberTable;